 static void GoalSemantics(){
  string root=Path.Combine(Path.GetTempPath(),"catheryne-endgame-goals-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
   var service=new EndgameService(root,new EndgameKnowledge(root,Feed),Account);service.Run("prepare","abyss",new Dictionary<string,object>());
   foreach(string mode in new[]{"abyss","stygian"}){string first="";int revision=0;foreach(string goal in new[]{"12층 9별","11층 8별","9층 7별"}){var recommendation=D(service.Run("recommend",mode,new Dictionary<string,object>{{"goal",goal},{"difficulty",5},{"expected_revision",revision},{"event_id","goal-"+revision++}}));string options=CatheryneTools.Json().Serialize(recommendation["options"]);if(first.Length==0)first=options;Check(options==first,"goal text remains an annotation, not an unverified filter");Check(EndgameService.S(recommendation,"goal")==goal,"original goal is retained for consultation");}bool rejected=false;try{service.Run("recommend",mode,new Dictionary<string,object>{{"floor",11},{"stars",8}});}catch(ArgumentException){rejected=true;}Check(rejected,"unsupported mechanical filters are rejected");}
  }finally{Directory.Delete(root,true);}
 }
